  <div class="space-y-8">
    <div class="relative overflow-hidden rounded-3xl border border-primary/20 bg-navy text-white shadow-sm">
      <div class="absolute inset-0" style="background-image: var(--motif-pattern); opacity: var(--motif-opacity, 0.2);"></div>
      <div class="absolute -top-10 -left-10 h-40 w-40 rounded-full bg-primary/10 blur-3xl"></div>
      <div class="absolute -bottom-10 -right-10 h-40 w-40 rounded-full bg-primary/5 blur-3xl"></div>

      <div class="relative p-6 sm:p-8 flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div class="flex items-center gap-5">
          <div
            class="size-12 sm:size-14 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center shrink-0 shadow-inner">
            <Icon icon="ph:storefront-bold" class="text-primary text-2xl sm:text-3xl" />
          </div>
          <div>
            <h1 class="text-xl sm:text-2xl font-black tracking-tight leading-none text-white">Ringkasan Seller</h1>
            <div class="text-slate-300 text-[10px] sm:text-xs font-bold mt-1 tracking-wide capitalize">Pantau performa dan operasional toko anda</div>
          </div>
        </div>
        <div class="flex flex-col sm:flex-row gap-3">
          <NuxtLink to="/dashboard/seller/products/add">
            <BaseButton variant="primary" icon="ph:plus-bold"
              class="h-11 px-5 font-black text-[10px] capitalize tracking-widest !rounded-xl shadow-lg shadow-primary/20">
